CREATE DEFINER=`u955681615_desarrollo`@`127.0.0.1` PROCEDURE `spActTrans` (IN `codtrans` VARCHAR(6), OUT `vrconsec` INT)   BEGIN
	-- #### Procedimiento que recibe transaccion, la actualiza y regresa el siguiente numero ####
	DECLARE vrUltimo INT;
	SELECT ( consec + 1 ) INTO vrUltimo 
	FROM im_trans
		WHERE cod_trans = codtrans;
	UPDATE im_trans SET consec = vrUltimo
	 	WHERE cod_trans = codtrans;
	SET vrconsec = vrUltimo;
END$$

CREATE DEFINER=`u955681615_desarrollo`@`127.0.0.1` PROCEDURE `spAddAlerta` (IN `xctabla` VARCHAR(30), IN `xctrans` VARCHAR(6), IN `xnid` INT, IN `xccod_asesor` VARCHAR(15))   BEGIN
		-- ### Procedimiento que crea la Alerta ###
		DECLARE xctipoper VARCHAR(6);
		DECLARE xcnomtipoper VARCHAR(20);
		DECLARE xntipoalerta INT;

		DECLARE vr_id_operacion INT;
		DECLARE vr_numero_trans, idtipoalerta INT;
		DECLARE vrcargodircompras, usudircompras VARCHAR(15);
		DECLARE vrcodtrans, vrcodtrans_ori VARCHAR(6);

		-- ### Busca tipo de Operacion ###
		SELECT tipo, nom_tipo INTO xctipoper,xcnomtipoper FROM ip_oper WHERE 
			tipo IN ( SELECT tipo_oper FROM im_trans WHERE cod_trans= xctrans ); 
		
		-- ### BUSCA alerta de la transaccion xctipoper ###
		SELECT id_tipoalerta INTO xntipoalerta FROM ap_tipoalerta WHERE 
		tabla_ini = xctabla AND programa = xctipoper;

		-- ### ADICIONO la Alerta,  58 = alerta en Comercial  ###
		     VALUES ( xntipoalerta,xnid, now(), CONCAT('ALERTA ',xcnomtipoper,' !!!'), 58, xccod_asesor );   
		
		-- SELECT xctipoper, xcnomtipoper , xntipoalerta,xctabla,xctrans,xccod_asesor;

    END$$

CREATE DEFINER=`u955681615_desarrollo`@`127.0.0.1` PROCEDURE `spDaPrecioUsd` (IN `xccod_item` VARCHAR(15), OUT `xfprecio_vta_usd` DECIMAL(12,2))   BEGIN 
	-- ### Procedure calcula precio de venta USD de artículos de inventario, según las políticas de la empresa. ###
	DECLARE xnmulti, xndesct, xntrans DECIMAL(6,3);
	DECLARE mensaje VARCHAR(80);
	DECLARE xcgrupo VARCHAR(20);
	DECLARE xfvr_prov DECIMAL(12,2);
	DECLARE xnmoneda INT;
	DECLARE xfmulti DECIMAL(6,3);
	-- Busca grupo y precio de venta al publico en lista precios proveedores.
	SELECT grupo_provee,vr_provee, id_moneda INTO xcgrupo,xfvr_prov,xnmoneda FROM cp_precios_provee WHERE ref_provee = xccod_item;
	SELECT valor INTO xfmulti FROM cp_multi_provee WHERE cod_grupo = xcgrupo AND id_fact = ( SELECT id_fact FROM cp_factor_provee WHERE fact_corto='salem');  
	SET xfprecio_vta_usd := ( xfvr_prov * xfmulti );
END$$

CREATE DEFINER=`u955681615_desarrollo`@`127.0.0.1` PROCEDURE `spListaRequerim` (IN `xnidreq` INT)   BEGIN
	-- ### Procedimiento que crea el requerimiento Interno REQ a partir de items del requerimiento de Clientes ###
	DECLARE xnidoper, xniddetalle, c1_xncantidad INT;
	DECLARE vr_numero_trans, idtipoalerta INT;
	DECLARE vrcargodircompras, usudircompras, c1_xccoditem VARCHAR(15);
	DECLARE xccodtrans, xccodtrans_ori VARCHAR(6);
	DECLARE c1_xfiva DECIMAL(4,2);
	DECLARE fin boolean DEFAULT FALSE;
	DECLARE c1_linea, c1_misional, c1_articulo VARCHAR(10);
	DECLARE c1_tipo, c1_marca, c1_idimport INT;
	DECLARE c1_observs TEXT;
	DECLARE c2_caract VARCHAR(10);
	DECLARE c2_vrcaract VARCHAR(100);
	
	DECLARE c1 CURSOR FOR SELECT vd.cod_item, vd.cantidad, vi.iva, vd.linea, vd.misional, vd.articulo, vd.tipo, vd.marca, vd.observs, vd.modo_import 
			FROM vr_requerimdet vd, im_items vi WHERE vd.id_requerim = xnidreq AND
					vd.a_compras = true AND vi.cod_item=vd.cod_item ORDER BY vd.id_reqdet;
					
	DECLARE c2 CURSOR FOR SELECT vc.caract, vc.vr_caract FROM vr_requerimcar vc WHERE vc.id_requerim = xnidreq AND 
	 		vc.id_reqdet = xniddetalle
	 		ORDER BY vc.id_reqdet,vc.id_reqcar;
	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET fin=true;
	
	-- Definición del manejador de excepciones para capturar errores SQL
	-- DECLARE EXIT HANDLER FOR SQLWARNING, NOT FOUND, SQLEXCEPTION
	-- BEGIN
		-- En caso de excepción, se muestra un mensaje y se realiza un rollback de la transacción
		-- SELECT SQLEXCEPTION.' !, transacción abortada' AS resultado;
		-- ROLLBACK;
	-- END ;
  
	-- Inicio de la transacción
	-- START TRANSACTION;

	SET xccodtrans := 'REQ';
	SELECT vr.cod_trans INTO xccodtrans_ori FROM vr_requerim vr WHERE vr.id_requerim = xnidreq;
        
	IF ( SELECT COUNT(*) FROM ir_operaciones WHERE trans_base = xccodtrans_ori AND num_antiguo_trans = xnidreq )<1 THEN
    		
			CALL spActTrans(xccodtrans,@vr_numero_trans);
            
			 			id_suc_cliente,codemple,id_area,c_costo,origen,destino,id_moneda,trm,subtotal,iva_total,descuento,
			 			cod_grabador,num_antiguo_trans,estado,id_financia,terminospago)
			SELECT xccodtrans, @vr_numero_trans, '0', vr.fechora, vr.fechora, vr.fechora, xccodtrans_ori, vr.suc_cliente, 
			 		vr.asesor_asignd, vr.area, '0', '0', '0','35', '0', '0', '0', '0', vr.cod_grabador, vr.id_requerim, '1', 
			 		'0', '0' FROM vr_requerim vr WHERE vr.id_requerim = xnidreq ;
			
			SET xnidoper := LAST_INSERT_ID();
			
			OPEN c1;
			FETCH c1 INTO c1_xccoditem, c1_xncantidad, c1_xfiva, c1_linea, c1_misional, c1_articulo, c1_tipo, c1_marca, c1_observs, c1_idimport;
				
			WHILE fin=false DO
							costo, valor_unitario, iva, fec_entrega_item, modo_import )
					VALUES(xnidoper,NULL,'0','0',c1_xccoditem, c1_xncantidad, '0', '0','0',c1_xfiva,'0000-00-00',c1_idimport );

				SET xniddetalle := LAST_INSERT_ID();

				  VALUES( xnidoper, xniddetalle, c1_linea, c1_misional, c1_articulo, c1_tipo, c1_marca, c1_observs );
				
				OPEN c2;
				FETCH c2 INTO c2_caract, c2_vrcaract;
				WHILE fin = false DO
					IF( c2_caract != NULL ) THEN
						VALUES ( xnidoper, xniddetalle,NULL,c2_caract, c2_vrcaract );
					END IF;
					FETCH c2 INTO c2_caract, c2_vrcaract;
				END WHILE;
				CLOSE c2;
				SET fin = false;
			FETCH c1 INTO c1_xccoditem, c1_xncantidad, c1_xfiva, c1_linea, c1_misional, c1_articulo, c1_tipo, c1_marca, c1_observs, c1_idimport;
			END WHILE;
			CLOSE c1;

			-- ### BUSCAR jefe de compras ###
			SELECT e.codemple INTO usudircompras FROM nm_empleados e 
			WHERE id_cargo IN ( SELECT valor FROM ap_param WHERE variable='cargo_dicom' );
            
			-- ### ejecuta spAddAlerta  ###
			CALL spAddAlerta('ir_operaciones','REQ',xnidoper,usudircompras);

	END IF;	
	-- Confirmar la transacción
	-- COMMIT;	
		
END$$

DELIMITER ;

