--
-- Estructura para la vista `clientes_x_region`
--
DROP TABLE IF EXISTS `clientes_x_region`;

CREATE ALGORITHM=UNDEFINED DEFINER=`u955681615_desarrollo`@`127.0.0.1` SQL SECURITY DEFINER VIEW `clientes_x_region`  AS SELECT `s`.`id_sucursal` AS `id_sucursal`, `s`.`numid` AS `numid`, `j`.`razon_social` AS `razon_social`, `p`.`apelli_nom` AS `apelli_nom`, `s`.`direccion` AS `direccion`, `s`.`telefono` AS `telefono`, `s`.`ciudad` AS `ciudad`, `c`.`nom_ciudad` AS `nom_ciudad`, `s`.`nom_sucur` AS `nom_suc`, `s`.`id_region` AS `id_region`, `r`.`nom_region` AS `nom_region` FROM ((`ap_regiones` `r` join `np_ciudades` `c`) join ((`nm_sucursal` `s` left join `nm_juridicas` `j` on(`j`.`numid` = `s`.`numid`)) left join `nm_personas` `p` on(`p`.`numid` = `s`.`numid`))) WHERE octet_length(`s`.`id_region`) > 6 AND `c`.`id_ciudad` = `s`.`ciudad` AND `r`.`id_region` = `s`.`id_region` ;

